Here's a simple JavaScript function that accepts text and posts a message to a Slack channel using the Slack API. Make sure you have the Slack API credentials (API key, Bot Token, Channel ID) before using this code.

```javascript
const axios = require('axios');

function postMessageToSlack(text, channelId) {
  const apiKey = 'your_api_key';
  const botToken = 'your_bot_token';

  const payload = {
    text: text,
    channel: channelId
  };

  const options = {
    method: 'POST',
    url: `https://slack.com/api/chat.postMessage`,
    headers: {
      'Authorization': `Bearer ${botToken}`,
      'Content-Type': 'application/json'
    },
    data: JSON.stringify(payload)
  };

  return axios(options)
    .then(response => response.data)
    .catch(error => console.error(error));
}

// Example usage
postMessageToSlack('Hello from JavaScript!', '#general')
  .then(response => console.log('Message posted successfully:', response))
  .catch(error => console.error('Error posting message:', error));
```

Replace `'your_api_key'` with your actual Slack API key and `'your_bot_token'` with your Bot Token. Also, replace `'#general'` with the desired channel ID where you want to post the message.

