  var url = `https://maps.googleapis.com/maps/api/geocode/json?address=${placeName}&key=${apiKey}`;

  var response = UrlFetchApp.fetch(url);
  var data = JSON.parse(response);

  if (data.results.length > 0) {
    var latitude = data.results[0].geometry.location.lat;
    var longitude = data.results[0].geometry.location.lng;
    return [latitude, longitude];
  } else {
    return ['', ''];
  }
}

function processColumn() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var column = 1; // Assuming the place names are in column A
  var rowStart = 2; // Assuming the data starts from row 2
  var rowEnd = sheet.getLastRow();

  for (var i = rowStart; i <= rowEnd; i++) {
    var placeName = sheet.getRange(i, column).getValue();
    var coords = searchPlace(placeName);
    sheet.getRange(i, column + 1).setValue(coords[0]); // Latitude
    sheet.getRange(i, column + 2).setValue(coords[1]); // Longitude
  }
}

processColumn();
```

Replace `'YOUR_API_KEY'` with your actual Google Maps API key. This script will search for the place name in the specified column (column A in this example) and store the latitude and longitude in the next two columns (columns B and C in this example). The script will process all rows in the sheet.

Here's a PHP custom function "smart_sort_array" that meets your requirements:

```php
function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        return $order === 'asc' ? $a['age'] - $b['age'] : $b['age'] - $a['age'];
    });
    return $set;
}
```

You can call this function with your set of associative arrays and the desired order ('asc' or 'desc') like this:

