    <button id="display-background-image">Display Background Image</button>
    <script src="script.js"></script>
</body>
</html>
```

And here's the JavaScript code (script.js) to display the background image:

```javascript
document.getElementById('display-background-image').addEventListener('click', () => {
    chrome.tabs.query({active: true, currentWindow: true}, tabs => {
        chrome.tabs.executeScript(tabs[0].id, {file: 'background_image.js'});
    });
});
```

Now, create a new file named "background_image.js" and add the following code:

```javascript
chrome.runtime.sendMessage({action: 'getBackgroundImage'}, function(response) {
    if (response.result) {
        const image = document.createElement('img');
        image.src = response.image;
        document.body.appendChild(image);
    } else {
        console.error('Failed to get background image.');
    }
});
```

Finally, open the HTML file in Google Chrome or another Chromium-based browser to see the background image of the user's computer on the desktop.

