```
/* Adjust widget layout */
.widget {
    width: 100%;
    margin-bottom: 20px;
}

.widget-area {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
}

.widget-area .widget {
    width: calc(33.33% - 10px);
    margin-bottom: 20px;
}

