```powershell
# Define the function to check if an SID exists in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher("DC=$domain")
    $searcher.Filter = "(objectClass=user)(SIDHistory*=$sid)"
    $results = $searcher.FindAll()
    return ($results.Count -gt 0)
}

# Define the function to recursively check folders for problematic ACLs
function CheckFolderACLs($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = (Get-Acl -Path $_.FullName).Access
        foreach ($access in $acl) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = $access.IdentityReference.SubString(6)
                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "Problematic ACL found in $($_.FullName) with SID $sid"
                }
            }
        }
        CheckFolderACLs($_.FullName)
    }
}

# Call the function to check the folder ACLs
$folderPath = "C:\Your_Folder_Path" # Replace with the path you want to check
CheckFolderACLs($folderPath)
```

